{{--
    Fable: the icon pattern, the ONE shared partial every area uses. It builds one small seamless tile, a 7 by 7 grid
    of single-colour icons, as an inline data-URI SVG (nothing is fetched from outside), and hands it to the caller as
    a class, a style attribute or the bare CSS value. The tile is laid over an area's own solid colour by the
    `.patterned` class (see fable-chrome.css).

    Takes:
      $area   rail, phone_header, footer, long_read, sections (section headers), 404, or shell (see below)
      $mode   class   prints `patterned`, or nothing
              style   prints ` style="--fable-pattern: url(...)"` (leading space, value escaped), or nothing
              band    prints a decorative brand-colour strip carrying the pattern (for the section headers and the 404), or nothing
              value   prints the bare CSS value `url("data:...")`, or nothing (for a caller that escapes it itself)
      $patternOverrides  (optional) an array of the pattern, pattern_strength, pattern_density and pattern_accent
              settings to use instead of the site's (the home-pattern wrapper passes its own parameters this way)

    It prints something only when the `pattern` setting is not `none` AND the area's own switch is on
    (fable_pattern_rail, _phone_header, _footer, _long_read, _sections, _404). The area `shell` is on when the rail, the
    phone header or the footer is on: layout.blade.php uses it once, in `style` mode, on the page shell. A custom
    property inherits, so the rail, the phone header and the footer need only `class` mode (they sit inside the shell),
    and the page carries the tile once, not once per area. A caller outside the shell uses `style` mode itself.

    Reads, once per include: pattern, pattern_strength, pattern_density, pattern_accent, fable_pattern_colour,
    fable_pattern_layout, fable_pattern_style and the area's switch.

    The icons are Phosphor (regular and fill weights, MIT licence), one path each on a 256 by 256 grid. To use your
    own, put the path data of any single-colour SVG icon in $icons and name it in a set.

    @package egberipiribo
    @since   0.1.0
--}}
@php
    $patternCfg = is_array($themeSettings ?? null) ? $themeSettings : [];
    $patternOver = is_array($patternOverrides ?? null) ? $patternOverrides : [];
    $patternSwitches = [
        'rail' => ['fable_pattern_rail', true],
        'phone_header' => ['fable_pattern_phone_header', true],
        'footer' => ['fable_pattern_footer', true],
        'long_read' => ['fable_pattern_long_read', true],
        'sections' => ['fable_pattern_sections', false],
        '404' => ['fable_pattern_404', false],
    ];
    $patternAreaOn = false;
    foreach ($patternSwitches as $patternAreaName => [$patternSwitchKey, $patternSwitchDefault]) {
        // (PHP turns the array key '404' into an integer, so the name is compared as a string.)
        $patternAreaName = (string) $patternAreaName;
        if (($area ?? '') === $patternAreaName || (($area ?? '') === 'shell' && in_array($patternAreaName, ['rail', 'phone_header', 'footer'], true))) {
            $patternAreaOn = $patternAreaOn || (bool) ($patternCfg[$patternSwitchKey] ?? $patternSwitchDefault);
        }
    }
    $patternSets = [
        'sections' => ['plant', 'paw-print', 'house-line', 'fork-knife', 'airplane-tilt', 'heartbeat', 'cpu'],
        'pets' => ['paw-print', 'bone', 'dog', 'cat', 'fish-simple', 'bird', 'heartbeat'],
        'home' => ['house-line', 'armchair', 'lamp', 'paint-roller', 'key', 'flower-tulip', 'leaf'],
        'food' => ['fork-knife', 'cooking-pot', 'carrot', 'coffee', 'bread', 'egg', 'leaf'],
    ];
    $patternSet = $patternOver['pattern'] ?? $patternCfg['pattern'] ?? 'none';
    $names = is_string($patternSet) ? ($patternSets[$patternSet] ?? null) : null;
    $patternCss = '';
@endphp
