        $tinted = '';
        for ($r = 0; $r < $count; $r++) {
            for ($c = 0; $c < $count; $c++) {
                $icon = ($c + $r * 3) % $count;
                $x = $c * $cell + ($cell - $size) / 2 + ($loose ? $nudges[($r * 2 + $c) % 7] * $cell : 0);
                $y = $r * $cell + ($cell - $size) / 2 + ($loose ? $nudges[($r + $c * 3) % 7] * $cell : 0);
                $turn = $loose ? $turns[($r * 3 + $c * 5) % 7] : 0;
                $half = number_format($size / 2, 1, '.', '');
                $use = "<use href='#i{$icon}' transform='translate(".number_format($x, 1, '.', '').' '.number_format($y, 1, '.', '').") rotate({$turn} {$half} {$half}) scale(".number_format($scale, 4, '.', '').")'/>";
