                for ($c = 0; $c <= $count; $c++) {
                    $dots .= "<circle cx='".($c * $cell)."' cy='".($r * $cell + $cell / 2)."' r='{$radius}'/>";
                    $dots .= "<circle cx='".($r * $cell + $cell / 2)."' cy='".($c * $cell)."' r='{$radius}'/>";
